  static String text(String language, String key) {
    final index = _keys.indexOf(key);
    if (index < 0) return key;
    final values = _values[language] ?? _values['en']!;
    return index < values.length ? values[index] : _values['en']![index];
  }

  static bool isRtl(String language) =>
      const {'fa', 'fa-AF', 'ar', 'ur', 'he'}.contains(language);
}
